pub trait LayerObject {
    fn id(&self) -> u64;                    // required: each member's own data
    fn describe(&self) -> String;           // required
    fn audit_tag(&self) -> String {         // shared default implementation
        format!("obj-{}: {}", self.id(), self.describe())
    }
}
pub struct User { pub id: u64, pub email: String }
impl LayerObject for User {
    fn id(&self) -> u64 { self.id }
    fn describe(&self) -> String { format!("user {}", self.email) }
}
